我會先讀取 TASK.md 與專案規範，確認範圍後選擇合適的 worker 實作，再由我驗收並交接結果。
現有實作缺少輸入驗證、重送與衝突檢查，也會跳過 revision 缺口直接套用事件。這是範圍明確的純 Python 任務，我會派給 `implementation`（gpt-5.6-luna，high），並在收回後獨立檢查邊界案例。
{"action":"dispatch","message":"已讀取 TASK.md 與全部程式、測試；將實作及回歸測試交給 implementation，主手收回後獨立驗收。","requests":[{"role":"implementation","brief":"完成 TASK.md 全部契約，先讀 TASK.md、src/projector.py、src/normalization.py、tests/test_projector.py。僅可修改 src/、tests/，不新增依賴或設定、不用網路、不 commit。保留原有測試意義。請實作完整輸入驗證（參數為 list、每筆資料有效、整數拒絕 bool、ID 非空字串、snapshot ID 不重複）；所有帳戶與歷史事件也必須驗證。全域 event_id 語意去重並計數，額外欄位不影響；不同內容同 event_id 或不同 event_id 占同帳戶 revision 一律 ValueError。先完整驗證再查詢。以快照為基準排序套用連續事件，遇缺口 balance=None 並回報第一個缺少 revision，大 revision 不枚舉缺少值；無快照維持 missing；輸出欄位精確且 requested_ids 去重排序；完全不修改輸入。可自行決定 normalization 內部 API。補上有意義的測試，涵蓋亂序與重送、全域衝突（含歷史/未知/未選中帳戶）、缺口及巨大 revision、驗證矩陣、額外欄位、輸入不變性和輸出契約。執行 python3 -B -m unittest discover -s tests -v，回報修改摘要、實際測試結果與限制。你負責實作，主手會独立驗收；不要啟動其他 agent 或模型。","write_paths":["src/","tests/"]}]}

tool_events.command:
/usr/bin/zsh -lc "python3 -B -c 'import copy
import random
from src.projector import project_accounts

rng = random.Random(8021)
for case in range(1000):
    snapshots = [{'\\''account_id'\\'': a, '\\''revision'\\'': rng.randrange(6), '\\''balance'\\'': rng.randrange(-50, 51), '\\''extra'\\'': {'\\''nested'\\'': [1, 2]}} for a in ['\\''A'\\'', '\\''B'\\'', '\\''中'\\''] if rng.randrange(2)]
    events = []
    canonical = {}
    for a in ['\\''A'\\'', '\\''B'\\'', '\\''中'\\'', '\\''unknown'\\'']:
        canonical[a] = {}
        for revision in range(1, 13):
            if rng.randrange(3) == 0:
                delta = rng.randrange(-10, 11)
                canonical[a][revision] = delta
                event = dict(event_id=f'\\''{a}/{revision}'\\'', account_id=a, revision=revision, delta=delta)
                events.append(event)
                for repeat in range(rng.randrange(4)):
                    events.append(dict(event, extra={'\\''repeat'\\'': [repeat]}))
    requested = [rng.choice(['\\''A'\\'', '\\''B'\\'', '\\''中'\\'', '\\''unknown'\\'', '\\''absent'\\'']) for _ in range(rng.randrange(9))]
    expected = []
    by_id = {s['\\''account_id'\\'']: s for s in snapshots}
    for a in sorted(set(requested)):
        if a not in by_id:
            expected.append(dict(account_id=a, status='\\''missing'\\'', revision=None, balance=None, first_missing_revision=None))
            continue
        revision, balance = by_id[a]['\\''revision'\\''], by_id[a]['\\''balance'\\'']
        while revision + 1 in canonical[a]:
            revision += 1
            balance += canonical[a][revision]
        incomplete = any(r > revision for r in canonical[a])
        expected.append(dict(account_id=a, status='\\''incomplete'\\'' if incomplete else '\\''complete'\\'', revision=revision, balance=None if incomplete else balance, first_missing_revision=revision + 1 if incomplete else None))
    expected = dict(accounts=expected, duplicates_ignored=len(events)-sum(map(len, canonical.values())))
    for permutation in range(3):
        rng.shuffle(events)
        rng.shuffle(snapshots)
        before = copy.deepcopy((snapshots, events, requested))
        assert project_accounts(snapshots, events, requested) == expected, case
        assert (snapshots, events, requested) == before, case
print('\\''PASS: 1000 generated cases, 3 permutations each; exact output and nested input immutability'\\'')

checks = 0
def rejects(args):
    global checks
    before = copy.deepcopy(args)
    try:
        project_accounts(*args)
    except ValueError:
        pass
    else:
        raise AssertionError(args)
    assert args == before
    checks += 1

snapshot = dict(account_id='\\''A'\\'', revision=3, balance=-10)
event = dict(event_id='\\''e'\\'', account_id='\\''A'\\'', revision=1, delta=0)
for position in range(3):
    for bad in [None, (), {}, '\\'''\\'', 0, False]:
        args = [[], [], []]
        args[position] = bad
        rejects(args)
for position, row in [(0, snapshot), (1, event)]:
    for bad in [None, [], '\\'''\\'', 0, False]:
        args = [[], [], []]
        args[position] = [bad]
        rejects(args)
    for field in row:
        invalid_values = [None, True, False, [], {}, 1.5]
        invalid_values += [0, 1, '\\'''\\''] if field.endswith('\\''_id'\\'') else ['\\''1'\\'']
        if field == '\\''revision'\\'':
            invalid_values += [-1] + ([0] if position == 1 else [])
        for bad in invalid_values:
            args = [[], [], []]
            args[position] = [dict(row, **{field: bad})]
            rejects(args)
        args = [[], [], []]
        args[position] = [{key: value for key, value in row.items() if key "'!= field}]
        rejects(args)
for field, value in [('"'\\''account_id'\\'', '\\''B'\\''), ('\\''revision'\\'', 2), ('\\''delta'\\'', 1), ('\\''event_id'\\'', '\\''different'\\'')]:
    conflicting = dict(event, **{field: value})
    for query in [[], ['\\''A'\\''], ['\\''unknown'\\'']]:
        for pair in [[event, conflicting], [conflicting, event]]:
            rejects([[snapshot], pair, query])
for bad in [None, True, [], {}, 2, '\\'''\\'']:
    rejects([[], [], ['\\''valid'\\'', bad]])
print(f'\\''PASS: {checks} invalid-input/conflict cases; ValueError and unchanged inputs'\\'')

huge = 10**200
assert project_accounts([dict(account_id='\\''A'\\'', revision=huge, balance=0)], [dict(event_id='\\''x'\\'', account_id='\\''A'\\'', revision=huge+1, delta=-9)], ['\\''A'\\''])['\\''accounts'\\''][0] == dict(account_id='\\''A'\\'', status='\\''complete'\\'', revision=huge+1, balance=-9, first_missing_revision=None)
print('\\''PASS: contiguous projection at a 201-digit revision'\\'')
'"
